/* ui/player-bar.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  // WaveSurfer replaces the compact seek bar with a full-width waveform row;
  // marking both the bar and the body lets CSS enlarge the row and the page
  // padding without measuring anything in JS.
  function setWaveMode(on) {
    P.bar.classList.toggle("has-waveform", on);
    document.body.classList.toggle("has-waveform", on);
  }

  /* ---------- loading progress (shown in the seek/waveform row) ---------- */

  function setLoadingProgress(value) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return;
    const percent = Math.round(Math.min(100, Math.max(0, numeric)));
    if (P.loadingPercentEl) P.loadingPercentEl.textContent = `${percent}%`;
    if (P.loadingFillEl) P.loadingFillEl.style.width = `${percent}%`;
    P.loadingEl?.setAttribute("aria-label", `${P.pt("loading")}: ${percent}%`);
  }

  function setLoading(active, progress = 0) {
    if (P.loadHideTimer) { window.clearTimeout(P.loadHideTimer); P.loadHideTimer = 0; }
    if (P.loadFallbackTimer) { window.clearTimeout(P.loadFallbackTimer); P.loadFallbackTimer = 0; }
    if (!P.loadingEl) return;
    P.loadingEl.hidden = !active;
    P.bar.classList.toggle("is-loading", !!active);
    if (!active) return;
    P.setLoadingProgress(progress);
    // Never leave the overlay stuck if a browser/library reports no progress.
    P.loadFallbackTimer = window.setTimeout(() => P.finishLoading(), 12000);
  }

  function finishLoading() {
    if (!P.loadingEl || P.loadingEl.hidden) return;
    P.setLoadingProgress(100);
    if (P.loadFallbackTimer) { window.clearTimeout(P.loadFallbackTimer); P.loadFallbackTimer = 0; }
    if (P.loadHideTimer) window.clearTimeout(P.loadHideTimer);
    P.loadHideTimer = window.setTimeout(() => {
      P.loadingEl.hidden = true;
      P.bar.classList.remove("is-loading");
      P.loadHideTimer = 0;
    }, 220);
  }

  // Wave engines report their own loading progress; the shared element's
  // buffered ranges would reach 100% long before the waveform is decoded.
  function usesNativeProgress() {
    return P.state.engine !== "wavesurfer" && P.state.engine !== "peaks";
  }

  function bufferedPercent() {
    if (!Number.isFinite(P.audio.duration) || P.audio.duration <= 0) {
      return P.audio.readyState >= 2 ? 100 : 0;
    }
    try {
      if (P.audio.buffered && P.audio.buffered.length) {
        const end = P.audio.buffered.end(P.audio.buffered.length - 1);
        if (Number.isFinite(end)) return (end / P.audio.duration) * 100;
      }
    } catch {}
    // readyState fallbacks for browsers that don't expose buffered ranges.
    return ({ 0: 0, 1: 15, 2: 45, 3: 80, 4: 100 })[P.audio.readyState] || 0;
  }

  function syncProgramLockUi() {
    if (!P.bar) return;
    P.bar.classList.toggle("is-program-locked", P.programLocked);
    ["playerPrev", "playerNext", "playerQueueToggle", "playerShuffle", "playerRepeat", "playerSeek"]
      .forEach((id) => {
        const el = P.$(id);
        if (el) el.disabled = P.programLocked;
      });
    document.querySelectorAll("[data-remix-action], [data-remix-file]").forEach((el) => {
      el.disabled = P.programLocked;
    });
  }

  function waveformColors() {
    return {
      waveColor: P.cssVar("--muted") || "#888888",
      progressColor: P.cssVar("--text") || "#ffffff",
      cursorColor: P.cssVar("--text") || "#ffffff",
    };
  }

  function showWaveMode() {
    P.hideEngineUi();
    P.waveform.hidden = false;
    P.seek.hidden = true;
    P.setWaveMode(true);
  }

  function hideWaveMode() {
    P.hideEngineUi();
    P.waveform.hidden = true;
    P.seek.hidden = false;
    P.setWaveMode(false);
  }

  // A double click on the WaveSurfer waveform pauses/resumes the same shared
  // <audio> element the rest of the player controls.
  function handleWaveDoubleClick(event) {
    event.preventDefault();
    if (!P.state.current) return;
    P.toggle();
  }

  /* ---------- playback core ---------- */

  function showBar() {
    P.bar.hidden = false;
    document.body.classList.add("has-player");
    if (P.hideTimer) { window.clearTimeout(P.hideTimer); P.hideTimer = 0; }
    void P.bar.offsetHeight;
    P.bar.classList.add("is-visible");
  }

  function hideBar(immediate = false) {
    P.bar.classList.remove("is-visible");
    const finish = () => {
      P.bar.hidden = true;
      document.body.classList.remove("has-player");
      P.hideTimer = 0;
    };
    if (immediate) finish();
    else P.hideTimer = window.setTimeout(finish, 300);
  }

  /* ---------- UI ---------- */

  function pulseElement(el, className = "is-pulsing") {
    if (!el || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
    el.classList.remove(className);
    void el.offsetWidth; // restart the animation even on a rapid second click
    el.classList.add(className);
    const done = () => {
      el.classList.remove(className);
      el.removeEventListener("animationend", done);
    };
    el.addEventListener("animationend", done);
  }

  function updatePlayState() {
    const playing = !!(P.state.current && !P.audio.paused && !P.audio.ended);
    P.bar.classList.toggle("is-playing", playing);
    const playButton = P.$("playerPlay");
    playButton.setAttribute("aria-label", playing ? P.pt("pause") : P.pt("play"));
    P.pulseElement(playButton);
    P.updateMediaSessionState();
    P.notify("playstate");
  }

  function updateMuteState() {
    const muted = P.audio.muted || P.state.volume === 0;
    P.bar.classList.toggle("is-muted", muted);
    P.$("playerMute").setAttribute("aria-label", muted ? P.pt("muteOn") : P.pt("muteOff"));
    P.$("playerMute").setAttribute("aria-pressed", String(muted));
    P.notify("volume");
  }

  function updateTime() {
    const duration = Number.isFinite(P.audio.duration) ? P.audio.duration : 0;
    const current = Number.isFinite(P.audio.currentTime) ? P.audio.currentTime : 0;
    P.seek.value = duration ? String(Math.round((current / duration) * 1000)) : "0";
    P.$("playerCurrent").textContent = P.formatTime(current);
    P.$("playerDuration").textContent = P.formatTime(duration);
  }

  function applyShuffle() {
    P.$("playerShuffle").setAttribute("aria-pressed", String(P.state.shuffle));
    P.$("playerShuffle").setAttribute("aria-label", P.state.shuffle ? P.pt("shuffleOn") : P.pt("shuffleOff"));
  }

  function applyRepeat() {
    const button = P.$("playerRepeat");
    button.dataset.repeat = P.state.repeat;
    button.setAttribute("aria-pressed", String(P.state.repeat !== "off"));
    button.setAttribute("aria-label", {
      off: P.pt("repeatOff"), all: P.pt("repeatAll"), one: P.pt("repeatOne"),
    }[P.state.repeat]);
  }
  Object.assign(P, { setWaveMode, setLoadingProgress, setLoading, finishLoading, usesNativeProgress, bufferedPercent, syncProgramLockUi, waveformColors, showWaveMode, hideWaveMode, handleWaveDoubleClick, showBar, hideBar, pulseElement, updatePlayState, updateMuteState, updateTime, applyShuffle, applyRepeat });
}
